pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 val, uint256 unlockTime, bool collectBeforeUnlock) public {
        // Val must be at least 1 ether to meet MinSum for Collect
        val = bound(val, 1 ether, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);
        // sender is a fresh address, not address(this)
        address sender = address(uint160(uint256(keccak256(abi.encode(val, unlockTime)))));
        vm.deal(sender, val);

        // Record block.timestamp before Put
        vm.prank(sender);
        c.Put{value: val}(unlockTime);
        uint256 putTimestamp = block.timestamp;

        // Decide whether to try Collect before unlock time
        if (collectBeforeUnlock) {
            // Warp to just before unlock time, so reference should NOT allow Collect
            vm.warp(unlockTime - 1);
        } else {
            // Warp to unlock time, Collect should succeed on reference
            vm.warp(unlockTime);
        }

        // We want to check: if Collect succeeds, block.timestamp must be >= putTimestamp
        // Because the bug sets unlockTime=0, it will succeed even when warped before unlockTime
        bool ok;
        // We must use an external helper to catch revert, since Collect can revert
        // But we can use try/catch via address(c).call, but Collect requires msg.sender
        // So we use prank and a low-level call
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", val));
        ok = success;

        // Assertion: Collect success implies that current block.timestamp >= putTimestamp
        assertTrue(!ok || block.timestamp >= putTimestamp);
    }
}

