pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 value, uint256 warpTime) public {
        // Keep values reasonable and avoid overflow
        vm.assume(value > 0 && value < 1e30);
        vm.assume(_unlockTime < 1e48);
        vm.assume(warpTime < 1e48);

        // Set up a sender with some ether
        address sender = address(0x1234);
        vm.deal(sender, value);

        // First Put to establish an initial unlockTime; use warpTime to set a known block.timestamp
        vm.warp(warpTime);
        vm.prank(sender);
        c.Put{value: value}(_unlockTime);

        // Record the unlockTime after the first Put
        uint256 initialUnlock = c.Acc(sender).unlockTime;

        // Advance time so that block.timestamp increases beyond the initial unlockTime if it wasn't already
        vm.warp(initialUnlock + 1 days);

        // Second Put with a small _unlockTime that is less than the new block.timestamp
        uint256 smallUnlockTime = initialUnlock > 0 ? initialUnlock - 1 : 0;
        vm.prank(sender);
        c.Put{value: 1}(smallUnlockTime);

        uint256 newUnlock = c.Acc(sender).unlockTime;

        // The reference rule: unlockTime after Put is always >= current block.timestamp
        // The mutant deletes the update, leaving unlockTime unchanged (still initialUnlock),
        // which may be < block.timestamp
        assertTrue(newUnlock >= block.timestamp);
    }
}

