pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 value) public {
        address sender = address(this);
        vm.assume(_unlockTime > 0);
        vm.assume(value < type(uint256).max / 2);
        vm.deal(sender, value);
        // Record current unlockTime
        (uint256 beforeUnlockTime,) = c.Acc(sender);
        // Perform Put with fuzzed _unlockTime and value
        vm.prank(sender);
        c.Put{value: value}(_unlockTime);
        // Get unlockTime after Put
        (uint256 afterUnlockTime,) = c.Acc(sender);
        // Invariant: after Put, unlockTime must be at least what it was before.
        // Reference C satisfies this because it sets unlockTime = max(_unlockTime, block.timestamp) >= beforeUnlockTime (since previous >= beforeUnlockTime, and max >= previous).
        // Buggy M never updates unlockTime, so afterUnlockTime == beforeUnlockTime; if _unlockTime < beforeUnlockTime this holds, but if _unlockTime > beforeUnlockTime, afterUnlockTime < _unlockTime <= beforeUnlockTime fails (if _unlockTime > beforeUnlockTime, reference increases unlockTime, bug keeps it unchanged, breaking afterUnlockTime >= beforeUnlockTime? No, bug keeps it unchanged so afterUnlockTime == beforeUnlockTime, which satisfies >=). Wait, difference is that reference can increase unlockTime, bug never does. So invariant "after any Put, unlockTime >= before" holds for both. Better property: after Put, unlockTime == max(beforeUnlockTime, max(_unlockTime, block.timestamp)). However simpler property: after Put with _unlockTime > beforeUnlockTime (and > block.timestamp), unlockTime must increase.
        // So require _unlockTime > beforeUnlockTime and _unlockTime > block.timestamp.
        if (_unlockTime > beforeUnlockTime && _unlockTime > block.timestamp) {
            assertTrue(afterUnlockTime > beforeUnlockTime);
        }
    }
}

