import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint112 msgValue) public {
        // Restrict msgValue so that balance addition does not overflow.
        // acc.balance is uint (uint256), msgValue is uint112 so that any
        // acc.balance + msg.value fits into uint256 without wrapping.
        // _unlockTime remains wide; the fuzzer can choose any future time.
        vm.deal(address(this), msgValue);

        // Record the arguments before calling Put.
        uint256 suppliedUnlockTime = _unlockTime;
        vm.prank(address(this));
        c.Put{value: msgValue}(_unlockTime);

        // After Put, the recorded unlockTime for the caller must be >= supplied _unlockTime.
        // The mutant sets unlockTime = block.timestamp, which is < _unlockTime when _unlockTime is in the future.
        (uint256 recordedUnlockTime, /* balance */) = c.Acc(address(this));
        assertTrue(recordedUnlockTime >= suppliedUnlockTime, "unlockTime must be >= supplied _unlockTime");
    }
}

