pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint112 futureOffset) public {
        // Restrict to a safe ETH range and a positive future offset
        amount = bound(amount, 1 ether, 100 ether);
        futureOffset = uint112(bound(futureOffset, 1, 365 days));
        uint unlockTime = block.timestamp + futureOffset;

        // Fund user1 and call Put with the future unlockTime
        address user1 = address(0x100);
        vm.deal(user1, amount);
        vm.prank(user1);
        c.Put{value: amount}(unlockTime);

        // Warp to a time strictly after the deposit but strictly before the intended unlockTime
        uint warpTime = block.timestamp + (futureOffset / 2);
        vm.warp(warpTime);

        // user1 tries to collect the full balance
        vm.prank(user1);
        try c.Collect(amount) {
            // If the mutant let Collect succeed before the future unlockTime, we detect the bug. 
            // The correct contract should revert here.
            assertTrue(false, "Collect succeeded before unlockTime on mutant");
        } catch {
            // The correct contract reverts, which is expected.
            assertTrue(true, "Collect correctly reverted before unlockTime");
        }
    }
}

