        // Warp forward to ensure unlockTime is passed
        vm.warp(block.timestamp + 1);

        // Record state before Collect
        uint256 contractBalanceBefore = address(c).balance;
        uint256 accBalanceBefore = c.Acc(caller).balance;

        // Collect the full amount
        vm.prank(caller);
        c.Collect(amount);

        // After Collect, ETH held by the contract must equal the sum of all Acc balances
        // Here there is only one depositor, so we check contract balance == Acc[caller].balance
        uint256 contractBalanceAfter = address(c).balance;
        uint256 accBalanceAfter = c.Acc(caller).balance;

        // Reference invariant: contract's ETH balance equals total Acc balances
        assertTrue(contractBalanceAfter == accBalanceAfter);
    }
}

