pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint8 extraDeposits) public {
        // Bound to practical values.
        amount = bound(amount, 1 ether, 100 ether);
        unlockTime = bound(unlockTime, 1, type(uint64).max);
        extraDeposits = uint8(bound(extraDeposits, 0, 5));

        address caller = address(uint160(uint256(keccak256(abi.encode(amount, unlockTime)))));
        // Keep caller distinct from LogFile/deployer
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        // Fund caller
        vm.deal(caller, (amount + 1 ether) * (extraDeposits + 2));
        vm.startPrank(caller);

        // Make initial deposit to establish unlocked balance
        c.Put{value: amount}(uint64(unlockTime));
        // Make some additional deposits to vary total balance; this does not break the invariant.
        for (uint8 i = 0; i < extraDeposits; i++) {
            c.Put{value: 1 ether}(uint64(unlockTime));
        }
        vm.stopPrank();

        // Advance time past unlockTime
        vm.warp(block.timestamp + unlockTime + 1);

        // Record pre-state
        uint256 preAccBalance = c.Acc(caller).balance;
        // Sum of all balances is impractical to compute for all fuzzed callers, so we compute
        // the contract's ETH liability locally: the only account with known balance is `caller`.
        // The property: contract ETH change must equal the net change in accounted balances.
        // Here: after a successful Collect of `amount`, caller's balance must drop by `amount`,
        // and contract ETH must drop by `amount`.  The bug prevents the balance drop, so the
        // ETH drop equals `amount` but the accounted balance does not change.
        uint256 preContractEth = address(c).balance;

        vm.prank(caller);
        try c.Collect(amount) returns () {
            // Collect succeeded
        } catch {
            // Collect reverted; skip assertion because the property only applies to successful Collect.
            return;
        }

        uint256 postAccBalance = c.Acc(caller).balance;
        uint256 postContractEth = address(c).balance;

        // Invariant: the caller's internal balance reduction exactly matches the ETH they received.
        // Pre-balance - post-balance == contract ETH reduction.
        // In correct C, preAccBalance - postAccBalance == preContractEth - postContractEth.
        // In buggy C, preAccBalance - postAccBalance == 0 while preContractEth - postContractEth > 0,
        // so the equality fails.
        assertEq(preAccBalance - postAccBalance, preContractEth - postContractEth, "ETH outflow must equal recorded balance deduction");
    }
}

